import{_ as t,c as o,o as n,ae as a}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Fluent Forms Integration","description":"Fluent Forms Integration","frontmatter":{"title":"Fluent Forms Integration","description":"Fluent Forms Integration"},"headers":[],"relativePath":"guide/data-sources/fluent-forms-integration.md","filePath":"guide/data-sources/fluent-forms-integration.md"}'),r={name:"guide/data-sources/fluent-forms-integration.md"};function s(i,e,l,u,d,m){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="fluent-forms-integration" tabindex="-1">Fluent Forms Integration <a class="header-anchor" href="#fluent-forms-integration" aria-label="Permalink to &quot;Fluent Forms Integration&quot;">​</a></h1><p>Fluent Forms** **is an amazing dynamic form plugin with 25+ form input fields, multiple integrations, conversational forms, conditional logic, and more. Ninja Tables and Fluent Forms integration lets you display all form entries in a table format on the front end. Here&#39;s a video on how this integration works. <a href="https://youtu.be/uMVnTYnKWM4" target="_blank" rel="noreferrer">https://youtu.be/uMVnTYnKWM4</a> Both the <strong>Ninja Tables</strong> and <strong>Fluent Forms</strong> are installed beforehand in the dashboard we&#39;re using.</p><h2 id="create-a-form-and-display-form-in-a-table" tabindex="-1">Create a Form and Display Form in a Table <a class="header-anchor" href="#create-a-form-and-display-form-in-a-table" aria-label="Permalink to &quot;Create a Form and Display Form in a Table&quot;">​</a></h2><p>Go to the Fluent Forms dashboard, create a form (here&#39;s a form named <strong>Contact</strong> <strong>Form</strong>) &amp; put some entries into it. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Fluent-Forms-1-scaled.webp" alt="Form Entries"></p><ul><li>The above image shows that all the required data has been entered into the form.</li><li>To show these entries in customized and designed Ninja Tables, simply connect your table to Fluent Forms.</li><li>Click <strong>Connect Fluent Forms</strong> from there, and give a title to your table. Then choose your preferred form using the box &quot;**Select a Form&quot; <strong>like</strong> **the below screenshot. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Fluent-Forms-2-scaled.webp" alt="Connect Fluent Forms"></li><li>After connecting your form, all fields of your selected form will now show up.</li></ul><p>From here, you can choose and save all fields or any unique field you wish to view in the table.</p><p><img src="https://ninjatables.com/wp-content/uploads/2022/09/Fluent-Forms-3-scaled.webp" alt="Select Entry Fields"></p><ul><li>When you&#39;re done selecting or deselecting the form fields, hit the &quot;Save&quot; button.</li></ul><p>Now a new table will be created with the form fields as table header and form entries as table data. <img src="https://ninjatables.com/wp-content/uploads/2023/01/fluent-forms-integration-5.png" alt="form entries in data table"></p><ul><li>Edit the table’s name, data type &amp; table style as well using Ninja Tables. Plus, Ninja tables also give you the option to customize table design, responsiveness, and table color.</li><li>Further customization can be done, such as - adding another **Your Message **column name. Select the Edit button that is just above the table.</li><li>After clicking there, you can notice all your form fields, like the screenshot below. <img src="https://ninjatables.com/wp-content/uploads/2023/01/fluent-forms-integration-7-1024x426.png" alt="Contact Table"> Use responsive breakpoints or stackable table features in this form data table if you need a cleaner look.</li></ul><h2 id="displaying-your-own-submissions-form-only" tabindex="-1">Displaying Your Own Submissions Form Only <a class="header-anchor" href="#displaying-your-own-submissions-form-only" aria-label="Permalink to &quot;Displaying Your Own Submissions Form Only&quot;">​</a></h2><p>If you choose to use Ninja Tables to display your form submissions, <strong>activate</strong> that from the configuration settings for Table Rows. <img src="https://ninjatables.com/wp-content/uploads/2023/01/fluent-forms-integration-11.png" alt="Own Submission Form"></p><h2 id="show-your-table-data-according-to-the-entry-type" tabindex="-1"><strong>Show Your Table Data According to the Entry Type</strong> <a class="header-anchor" href="#show-your-table-data-according-to-the-entry-type" aria-label="Permalink to &quot;**Show Your Table Data According to the Entry Type**&quot;">​</a></h2><p>You can also show table data based on the Entry type. Go to the form where all the required data has been entered.</p><ul><li>Click the **Change Status **field and select your entry type Read / Unread / Trashed. <img src="https://ninjatables.com/wp-content/uploads/2023/01/fluent-forms-integration-12.png" alt="Show Table Data According to the Entry Type"></li><li>Now go to your Ninja Table, which is connected with Fluent Forms. <strong>Entry Type</strong> enables you to select what type of entries you want to show from fluent forms.</li><li>Choose your Entry type as per your needs. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Fluent-Forms-5-scaled.webp" alt="Entry Type"></li><li>Here is the result of the table data, which depends on the <strong>Status</strong> which was chosen. <img src="https://ninjatables.com/wp-content/uploads/2023/01/fluent-forms-integration-14.png" alt="Status"> The combination of Fluent Forms and Ninja Tables is the most powerful one! And undoubtedly, it is very helpful for your website. Fluent Forms integration with Ninja Tables unlocks a lot more opportunities for lead generation and sales increase. Try this combo once and enjoy the magic!</li></ul>',15)])])}const p=t(r,[["render",s]]);export{h as __pageData,p as default};
